package com.frazersan.overheadreminders;

import java.awt.Color;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.IntSupplier;
import java.util.function.Supplier;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.VarbitID;

/** Samples complete game ticks so inventory, XP and boost changes from one action agree. */
final class BoostReminderController
{
    private static final List<Skill> TRACKED = Arrays.asList(Skill.ATTACK, Skill.STRENGTH,
        Skill.DEFENCE, Skill.MAGIC, Skill.RANGED, Skill.SLAYER, Skill.AGILITY);

    private static final class Rule
    {
        final BoostReminderType type;
        final BooleanSupplier enabled;
        final IntSupplier threshold;
        final IntSupplier timeout;
        final Supplier<String> message;
        final Supplier<Color> color;
        boolean notified;
        boolean trackingPie;
        boolean trackingSupply;

        Rule(BoostReminderType type, BooleanSupplier enabled, IntSupplier threshold,
            IntSupplier timeout, Supplier<String> message, Supplier<Color> color)
        {
            this.type = type;
            this.enabled = enabled;
            this.threshold = threshold;
            this.timeout = timeout;
            this.message = message;
            this.color = color;
        }
    }

    private final Client client;
    private final OverheadNotificationsConfig config;
    private final NotificationStore notifications;
    private final List<Rule> rules;
    private final Map<Skill, Integer> experience = new EnumMap<>(Skill.class);
    private final Map<Skill, Integer> bonuses = new EnumMap<>(Skill.class);
    private boolean combatActivity;
    // A Divine expiry belongs to the Divine reminder until another boost is applied.
    private final EnumSet<Skill> divineEpisodes = EnumSet.noneOf(Skill.class);
    private final EnumSet<Skill> boostedAgain = EnumSet.noneOf(Skill.class);
    private EnumSet<Skill> previousSupplies = EnumSet.noneOf(Skill.class);

    @Inject
    BoostReminderController(Client client, OverheadNotificationsConfig config, NotificationStore notifications)
    {
        this.client = client;
        this.config = config;
        this.notifications = notifications;
        rules = Arrays.asList(
            new Rule(BoostReminderType.MELEE, config::meleeBoostEnabled, config::meleeBoostThreshold,
                () -> ReminderType.MELEE.duration(config), config::meleeBoostMessage, config::meleeBoostColor),
            new Rule(BoostReminderType.MAGIC, config::magicBoostEnabled, config::magicBoostThreshold,
                () -> ReminderType.MAGIC_BOOST.duration(config), config::magicBoostMessage, config::magicBoostColor),
            new Rule(BoostReminderType.RANGED, config::rangedBoostEnabled, config::rangedBoostThreshold,
                () -> ReminderType.RANGED.duration(config), config::rangedBoostMessage, config::rangedBoostColor),
            new Rule(BoostReminderType.WILD_PIE, config::wildPieEnabled, config::wildPieThreshold,
                () -> ReminderType.WILD_PIE.duration(config), config::wildPieMessage, config::wildPieColor),
            new Rule(BoostReminderType.SUMMER_PIE, config::summerPieEnabled, config::summerPieThreshold,
                () -> ReminderType.SUMMER_PIE.duration(config), config::summerPieMessage, config::summerPieColor));
    }

    void onStatChanged(StatChanged event)
    {
        Skill skill = event.getSkill();
        if (!TRACKED.contains(skill) || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        Integer previousXp = experience.put(skill, event.getXp());
        sampleBonus(skill, event.getLevel(), event.getBoostedLevel());
        if (previousXp != null && event.getXp() > previousXp && client.getLocalPlayer() != null
            && client.getLocalPlayer().getInteracting() != null)
        {
            if (isCombatSkill(skill))
            {
                combatActivity = true;
            }
        }
    }

    void onGameTick()
    {
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
        {
            return;
        }
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null)
        {
            combatActivity = false;
            boostedAgain.clear();
            return;
        }
        for (Skill skill : TRACKED)
        {
            experience.putIfAbsent(skill, client.getSkillExperience(skill));
            sampleBonus(skill, client.getRealSkillLevel(skill), client.getBoostedSkillLevel(skill));
        }
        for (Skill skill : TRACKED)
        {
            if (!config.enableDivinePot())
            {
                divineEpisodes.remove(skill);
            }
            else if (divineBoostActive(skill))
            {
                divineEpisodes.add(skill);
            }
            else if (boostedAgain.contains(skill))
            {
                divineEpisodes.remove(skill);
            }
        }
        EnumSet<Skill> available = BoostItems.available(inventory.getItems(),
            client.getVarbitValue(VarbitID.IMBUED_HEART_TIMER) == 0);
        for (Rule rule : rules)
        {
            update(rule, available);
        }
        previousSupplies = available;
        combatActivity = false;
        boostedAgain.clear();
    }

    private void sampleBonus(Skill skill, int realLevel, int boostedLevel)
    {
        if (realLevel <= 0)
        {
            return;
        }
        int bonus = boostedLevel - realLevel;
        Integer previous = bonuses.put(skill, bonus);
        if (previous != null && bonus < previous && isCombatSkill(skill)
            && client.getLocalPlayer() != null && client.getLocalPlayer().getInteracting() != null)
        {
            combatActivity = true;
        }
        if (previous != null && bonus > 0 && bonus > previous)
        {
            boostedAgain.add(skill);
        }
    }

    private void update(Rule rule, EnumSet<Skill> available)
    {
        if (!rule.enabled.getAsBoolean())
        {
            clear(rule);
            return;
        }
        boolean low = false;
        boolean eligible = false;
        boolean active = !rule.type.combat || combatActivity;
        boolean reapplied = false;
        for (Skill skill : rule.type.skills)
        {
            if (!bonuses.containsKey(skill))
            {
                continue;
            }
            int bonus = bonuses.get(skill);
            boolean supply = available.contains(skill);
            if (rule.type.combat && supply) rule.trackingSupply = true;
            if (!rule.type.combat && bonus > 0 && (supply || previousSupplies.contains(skill)))
            {
                // Continue tracking after the final half-pie is eaten.
                rule.trackingPie = true;
            }
            boolean missingSupplyReminder = rule.trackingSupply && config.showOutOfSupplies();
            boolean canRemind = rule.type.combat
                ? (supply || missingSupplyReminder) && !fixedBoostActive(skill) && !divineEpisodes.contains(skill)
                : rule.trackingPie;
            eligible |= canRemind;
            low |= canRemind && bonus <= rule.threshold.getAsInt();
            reapplied |= boostedAgain.contains(skill);
        }
        if (!eligible)
        {
            notifications.remove(rule.type.key);
            rule.notified = false;
            return;
        }
        if (reapplied || !low)
        {
            notifications.remove(rule.type.key);
            rule.notified = false;
            return;
        }
        if (active && !rule.notified)
        {
            int timeout = rule.timeout.getAsInt();
            notifications.show(rule.type.key, rule.message.get(), rule.color.get(),
                timeout);
            rule.notified = true;
        }
    }

    private boolean fixedBoostActive(Skill skill)
    {
        if (client.getVarbitValue(VarbitID.NZONE_OVERLOAD_POTION_EFFECTS) > 0
            || client.getVarbitValue(VarbitID.RAIDS_OVERLOAD_TIMER) > 0
            || client.getVarbitValue(VarbitID.TOA_MIDRAIDLOOT_STATS_TIMER) > 0)
        {
            return true;
        }
        return divineBoostActive(skill)
            || (skill == Skill.MAGIC && client.getVarbitValue(VarbitID.SATURATED_HEART_TIME) > 0);
    }

    private boolean divineBoostActive(Skill skill)
    {
        switch (skill)
        {
            case ATTACK:
                return client.getVarbitValue(VarbitID.DIVINEATTACK_POTION_TIME) > 0
                    || client.getVarbitValue(VarbitID.DIVINECOMBAT_POTION_TIME) > 0;
            case STRENGTH:
                return client.getVarbitValue(VarbitID.DIVINESTRENGTH_POTION_TIME) > 0
                    || client.getVarbitValue(VarbitID.DIVINECOMBAT_POTION_TIME) > 0;
            case MAGIC:
                return client.getVarbitValue(VarbitID.DIVINEMAGIC_POTION_TIME) > 0
                    || client.getVarbitValue(VarbitID.DIVINEBATTLEMAGE_POTION_TIME) > 0;
            case RANGED:
                return client.getVarbitValue(VarbitID.DIVINERANGE_POTION_TIME) > 0
                    || client.getVarbitValue(VarbitID.DIVINEBASTION_POTION_TIME) > 0;
            default:
                return false;
        }
    }

    private static boolean isCombatSkill(Skill skill)
    {
        return skill == Skill.ATTACK || skill == Skill.STRENGTH || skill == Skill.DEFENCE
            || skill == Skill.MAGIC || skill == Skill.RANGED;
    }
    private void clear(Rule rule)
    {
        notifications.remove(rule.type.key);
        rule.notified = false;
        rule.trackingPie = false;
        rule.trackingSupply = false;
    }

    void reset()
    {
        for (Rule rule : rules)
        {
            clear(rule);
        }
        experience.clear();
        bonuses.clear();
        combatActivity = false;
        boostedAgain.clear();
        previousSupplies.clear();
        divineEpisodes.clear();
    }
}

package com.frazersan.overheadreminders;

import net.runelite.api.Skill;

/** Stable notification keys keep each boost reminder independent in the stack. */
enum BoostReminderType
{
    MELEE("Melee Boost", true, Skill.STRENGTH),
    MAGIC("Magic Boost", true, Skill.MAGIC),
    RANGED("Ranged Boost", true, Skill.RANGED),
    WILD_PIE("Wild Pie", false, Skill.SLAYER),
    SUMMER_PIE("Summer Pie", false, Skill.AGILITY);

    final String key;
    final boolean combat;
    final Skill[] skills;

    BoostReminderType(String key, boolean combat, Skill... skills)
    {
        this.key = key;
        this.combat = combat;
        this.skills = skills;
    }
}

package com.frazersan.overheadreminders;

import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.client.config.ConfigManager;

/** Update stored old defaults once, preserving other values and later user edits. */
final class ConfigDefaultsMigration
{
    private static final String GROUP = "overheadreminder";
    private static final String REVISION = "tidyDefaultsRevision";

    static void apply(ConfigManager manager)
    {
        applyOldDefaults(manager);
        if (!"1".equals(manager.getConfiguration(GROUP, "sharedTimerDefaultsRevision")))
        {
            String[][] customTimers = {
                {"lowPrayerDuration", "lowPrayerUseGlobalTimer"},
                {"meleeBoostTimeout", "meleeBoostUseGlobalTimer"},
                {"magicBoostTimeout", "magicBoostUseGlobalTimer"},
                {"rangedBoostTimeout", "rangedBoostUseGlobalTimer"},
                {"wildPieTimeout", "wildPieUseGlobalTimer"},
                {"summerPieTimeout", "summerPieUseGlobalTimer"}
            };
            for (String[] custom : customTimers)
            {
                String duration = manager.getConfiguration(GROUP, custom[0]);
                if (duration != null && !"15".equals(duration)
                    && manager.getConfiguration(GROUP, custom[1]) == null)
                {
                    manager.setConfiguration(GROUP, custom[1], "false");
                }
            }
            manager.setConfiguration(GROUP, "sharedTimerDefaultsRevision", "1");
        }
        if (!"1".equals(manager.getConfiguration(GROUP, "hornActiveDefaultsRevision")))
        {
            String horn = manager.getConfiguration(GROUP, "soulflameHornMessage");
            if ("Blow Soulflame Horn".equals(horn) || "Soulflame Horn Active!".equals(horn))
            {
                manager.setConfiguration(GROUP, "soulflameHornMessage", "Soulflame Horn Active");
            }
            manager.setConfiguration(GROUP, "hornActiveDefaultsRevision", "1");
        }
        if ("1".equals(manager.getConfiguration(GROUP, "actionDefaultsRevision")))
        {
            return;
        }
        // Only replace exact former defaults. Never disable a saved enabled choice.
        String[][] messages = {
            {"divinePotMessage", "Divine Expired!", "Drink Divine"},
            {"saturatedHeartMessage", "Saturated Heart Expired!", "Invigorate Saturated Heart"},
            {"meleeBoostMessage", "Melee Boost", "Drink Melee Boost"},
            {"magicBoostMessage", "Magic Boost", "Drink Magic Boost"},
            {"rangedBoostMessage", "Range Boost", "Drink Range Boost"},
            {"overloadMessage", "Overload Expired!", "Drink Overload"},
            {"smellingSaltMessage", "Smelling Salt Expired!", "Use Smelling Salt"},
            {"thrallMessage", "Thrall Expired!", "Cast Thrall"},
            {"deathChargeMessage", "Death Charge Ready!", "Cast Death Charge"},
            {"markOfDarknessMessage", "Mark of Darkness expired!", "Cast Mark of Darkness"},
            {"WardOfArceuusMessage", "Ward of Arceuus expired!", "Cast Ward of Arceuus"},
            {"surgePotionMessage", "Surge Potion Ready!", "Drink Surge"},
            {"staminaMessage", "Stamina potion Expired!", "Drink Stamina"},
            {"antiPoisonMessage", "AntiPoison Expired!", "Drink Antipoison"},
            {"venomMessage", "Venom protection Expired!", "Drink Anti-venom"},
            {"antifireMessage", "Antifire protection Expired!", "Drink Antifire"}
        };
        for (String[] message : messages)
        {
            if (message[1].equals(manager.getConfiguration(GROUP, message[0])))
            {
                manager.setConfiguration(GROUP, message[0], message[2]);
            }
        }
        manager.setConfiguration(GROUP, "actionDefaultsRevision", "1");
    }

    private static void applyOldDefaults(ConfigManager manager)
    {
        if ("1".equals(manager.getConfiguration(GROUP, REVISION)))
        {
            return;
        }
        Map<String, String[]> replacements = new LinkedHashMap<>();
        replacements.put("overheadDisplayTime", new String[] {"3", "15"});
        replacements.put("lowPrayerMessage", new String[] {"LOW PRAYER!", "Low Prayer"});
        replacements.put("meleeBoostMessage", new String[] {"MELEE BOOST LOW!", "Melee Boost"});
        replacements.put("magicBoostMessage", new String[] {"MAGIC BOOST LOW!", "Magic Boost"});
        replacements.put("rangedBoostMessage", new String[] {"RANGED BOOST LOW!", "Range Boost"});
        replacements.put("wildPieMessage", new String[] {"SLAYER BOOST LOW!", "Slayer Boost"});
        replacements.put("summerPieMessage", new String[] {"AGILITY BOOST LOW!", "Agility Boost"});
        for (Map.Entry<String, String[]> entry : replacements.entrySet())
        {
            String[] values = entry.getValue();
            if (values[0].equals(manager.getConfiguration(GROUP, entry.getKey())))
            {
                manager.setConfiguration(GROUP, entry.getKey(), values[1]);
            }
        }
        manager.setConfiguration(GROUP, REVISION, "1");
    }
}

