import java.util.List;
import java.util.Map;
import java.util.function.IntSupplier;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarPlayerID;

/** One warning per effect cycle, shared by early warnings and chat expiry events. */
final class TimedReminderController
{
    private static final class Counter
    {
        final IntSupplier value;
        final IntSupplier unitTicks;
        int previous;
        int changedAt;

        Counter(IntSupplier value, IntSupplier unitTicks)
        {
            this.value = value;
            this.unitTicks = unitTicks;
        }
    }

    private static final class Effect
    {
        final ReminderType type;
        final List<Counter> counters = new ArrayList<>();
        boolean warned;
        boolean latestExpiry;

        Effect(ReminderType type) { this.type = type; }
    }

    private int adrenalineEnd;
    private final Client client;
    private final OverheadNotificationsConfig config;
    private final NotificationStore notifications;
    private final Map<ReminderType, Effect> effects = new EnumMap<>(ReminderType.class);

    TimedReminderController(Client client, OverheadNotificationsConfig config, NotificationStore notifications)
    {
        this.client = client;
        this.config = config;
        this.notifications = notifications;
        for (int id : new int[] {VarbitID.DIVINEATTACK_POTION_TIME, VarbitID.DIVINESTRENGTH_POTION_TIME,
            VarbitID.DIVINEDEFENCE_POTION_TIME, VarbitID.DIVINECOMBAT_POTION_TIME,
            VarbitID.DIVINEMAGIC_POTION_TIME, VarbitID.DIVINEBATTLEMAGE_POTION_TIME,
            VarbitID.DIVINERANGE_POTION_TIME, VarbitID.DIVINEBASTION_POTION_TIME})
        {
            varbit(ReminderType.DIVINE, id, 1);
        }
        // Saturated Heart's effect and recharge end together. The shared heart
        // recharge counter is in ten-tick units, unlike Divine's one-tick counters.
        add(ReminderType.HEART, () -> client.getVarbitValue(VarbitID.SATURATED_HEART_TIME) > 0
            ? Math.max(1, client.getVarbitValue(VarbitID.IMBUED_HEART_TIMER)) : 0, () -> 10);
        add(ReminderType.STAMINA, () -> client.getVarbitValue(VarbitID.STAMINA_ACTIVE) > 0
            ? Math.max(1, client.getVarbitValue(VarbitID.STAMINA_DURATION)) : 0, () -> 10);
        varbit(ReminderType.PRAYER_REGEN, VarbitID.PRAYER_REGENERATION_POTION_TIMER, 12);
        add(ReminderType.PRAYER_ENHANCE, () -> client.getVarbitValue(VarbitID.RAIDS_PRAYERENHANCE_TIMER),
            () -> Math.max(1, client.getVarbitValue(VarbitID.RAIDS_PRAYERENHANCE_RATE)));
        varbit(ReminderType.OVERLOAD, VarbitID.NZONE_OVERLOAD_POTION_EFFECTS, 25);
        varbit(ReminderType.OVERLOAD, VarbitID.RAIDS_OVERLOAD_TIMER, 25);
        varbit(ReminderType.OVERLOAD, VarbitID.DEADMAN_OVERLOAD_POTION_EFFECTS, 25);
        varbit(ReminderType.SALTS, VarbitID.TOA_MIDRAIDLOOT_STATS_TIMER, 25);
        varbit(ReminderType.SURGE, VarbitID.SURGE_POTION_TIMER, 10);
        add(ReminderType.ADRENALINE, this::adrenalineTicks, () -> 1);
        varbit(ReminderType.ANTIFIRE, VarbitID.ANTIFIRE_POTION, 30);
        varbit(ReminderType.ANTIFIRE, VarbitID.SUPER_ANTIFIRE_POTION, 20);
        effects.get(ReminderType.ANTIFIRE).latestExpiry = true;
        add(ReminderType.ANTIPOISON, () -> Math.max(0, -client.getVarpValue(VarPlayerID.POISON)), () -> 30);
        add(ReminderType.VENOM, () -> Math.max(0, -client.getVarpValue(VarPlayerID.POISON) - 38), () -> 30);
        add(ReminderType.THRALL, () -> spellTicks(VarClientID.BUFF_RESURRECTION_ACTIVE_START,
            client.getVarcIntValue(VarClientID.BUFF_RESURRECTION_ACTIVE_DURATION) - 3), () -> 1);
        add(ReminderType.MARK, () -> spellTicks(VarClientID.BUFF_MARK_OF_DARKNESS_START,
            client.getVarcIntValue(VarClientID.BUFF_MARK_OF_DARKNESS_DURATION)), () -> 1);
        add(ReminderType.WARD, () -> spellTicks(VarClientID.BUFF_WARD_OF_ARCEUUS_ACTIVE_START,
            client.getRealSkillLevel(Skill.MAGIC)), () -> 1);
    }

    private int adrenalineTicks()
    {
        if (client.getVarbitValue(VarbitID.TOA_MIDRAIDLOOT_ENERGY_ACTIVE) <= 0) return 0;
        adrenalineEnd = client.getVarcIntValue(VarClientID.BUFF_TOA_MIDRAIDLOOT_ENERGY_END);
        return Math.max(0, adrenalineEnd - client.getVarpValue(VarPlayerID.MAP_CLOCK));
    }

    private int spellTicks(int startVarc, int duration)
    {
        int start = client.getVarcIntValue(startVarc);
        int elapsed = client.getVarpValue(VarPlayerID.MAP_CLOCK) - start;
        return start > 0 && elapsed >= 0 ? Math.max(0, duration - elapsed) : 0;
    }

    private void varbit(ReminderType type, int id, int unit)
    {
        add(type, () -> client.getVarbitValue(id), () -> unit);
    }

    private void add(ReminderType type, IntSupplier value, IntSupplier unit)
    {
        effects.computeIfAbsent(type, Effect::new).counters.add(new Counter(value, unit));
    }

    void onGameTick()
    {
        int tick = client.getTickCount();
        for (Effect effect : effects.values())
        {
            int remaining = effect.latestExpiry ? 0 : Integer.MAX_VALUE;
            boolean active = false;
            boolean wasActive = false;
            boolean refreshed = false;
            for (Counter counter : effect.counters)
            {
                wasActive |= counter.previous > 0;
                int current = Math.max(0, counter.value.getAsInt());
                refreshed |= current > counter.previous;
                if (current != counter.previous) counter.changedAt = tick;
                if (current > 0)
                {
                    active = true;
                    // Follow observed counter boundaries between coarse server updates.
                    // Clamp above zero until the server confirms that the effect ended.
                    int ticks = Math.max(1, current * counter.unitTicks.getAsInt()
                        - Math.max(0, tick - counter.changedAt));
                    remaining = effect.latestExpiry ? Math.max(remaining, ticks) : Math.min(remaining, ticks);
                }
                counter.previous = current;
            }
            if (!effect.type.enabled(config))
            {
                effect.warned = false;
                notifications.remove(effect.type.key);
                continue;
            }
            if (refreshed)
            {
                effect.warned = false;
                notifications.remove(effect.type.key);
            }
            if (effect.type == ReminderType.ADRENALINE && wasActive && !active)
            {
                if (adrenalineEnd > 0 && client.getVarpValue(VarPlayerID.MAP_CLOCK) >= adrenalineEnd)
                {
                    if (!effect.warned)
                    {
                        effect.type.show(config, notifications);
                        effect.warned = true;
                    }
                }
                else
                {
                    // Leaving the raid or losing the effect early is not a natural expiry.
                    notifications.remove(effect.type.key);
                    effect.warned = false;
                }
            }
            if (active && !effect.warned)
            {
                notifications.remove(effect.type.key);
                int early = effect.type.earlySeconds(config);
                if (early > 0 && remaining * 600L <= early * 1000L)
                {
                    effect.type.show(config, notifications);
                    effect.warned = true;
                }
            }
        }
    }

    /** Chat expiry must not add or refresh a warning already issued early. */
    void onExpiry(ReminderType type)
    {
        Effect effect = effects.get(type);
        if (effect == null)
        {
            type.show(config, notifications);
        }
        else if (!effect.warned)
        {
            type.show(config, notifications);
            effect.warned = true;
        }
    }

    void reapplied(ReminderType type)
    {
        notifications.remove(type.key);
        Effect effect = effects.get(type);
        if (effect != null) effect.warned = false;
    }

    void reset()
    {
        adrenalineEnd = 0;
        for (Effect effect : effects.values())
        {
            effect.warned = false;
            for (Counter counter : effect.counters)
            {
                counter.previous = 0;
                counter.changedAt = 0;
            }
        }
    }
}

package com.frazersan.overheadreminders;

/** A game message mapped to one reminder type. */
final class TriggerRule
{
    final ReminderType type;
    private final String keyword;

    TriggerRule(ReminderType type, String keyword)
    {
        this.type = type;
        this.keyword = keyword;
    }

    boolean matches(String message) { return message.contains(keyword); }
}

package com.frazersan.overheadreminders;

import java.util.EnumSet;
import net.runelite.api.Item;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class BoostItemsTest
{
    private static EnumSet<Skill> supplies(int id)
    {
        return BoostItems.available(new Item[] {new Item(id, 1)}, true);
    }

    @Test
    public void everyRegularSuperCombatDoseRestoresBothMeleeSkills()
    {
        for (int id : new int[] {ItemID._1DOSE2COMBAT, ItemID._2DOSE2COMBAT,
            ItemID._3DOSE2COMBAT, ItemID._4DOSE2COMBAT})
        {
            assertEquals(EnumSet.of(Skill.ATTACK, Skill.STRENGTH), supplies(id));
        }
        assertEquals(EnumSet.of(Skill.STRENGTH), supplies(ItemID.STRENGTH4));
        assertEquals(EnumSet.of(Skill.ATTACK), supplies(ItemID._1DOSE2ATTACK));
    }

    @Test
    public void magicAndRangedPotionFamiliesAndMixesAreRecognized()
    {
        for (int id : new int[] {ItemID._1DOSE1MAGIC, ItemID._2DOSE1MAGIC,
            ItemID._3DOSE1MAGIC, ItemID._4DOSE1MAGIC, ItemID._4DOSEBATTLEMAGE,
            ItemID._4DOSEANCIENTBREW, ItemID._1DOSEFORGOTTENBREW, ItemID._1DOSEMAGICESS,
            ItemID.BRUTAL_1DOSE1MAGIC, ItemID.RAIDS_VIAL_KODAI_STRONG_1, ItemID.NZONE1DOSE2MAGICPOTION})
        {
            assertTrue("Magic source " + id, supplies(id).contains(Skill.MAGIC));
        }
        for (int id : new int[] {ItemID._1DOSERANGERSPOTION, ItemID._2DOSERANGERSPOTION,
            ItemID._3DOSERANGERSPOTION, ItemID._4DOSERANGERSPOTION, ItemID._1DOSEBASTION,
            ItemID._1DOSEARMADYLBREW, ItemID.BRUTAL_1DOSERANGERSPOTION,
            ItemID.RAIDS_VIAL_TWISTED_STRONG_1, ItemID.NZONE1DOSE2RANGERSPOTION})
        {
            assertTrue("Ranged source " + id, supplies(id).contains(Skill.RANGED));
        }
    }

    @Test
    public void divineSaturatedAndOtherFixedBoostSuppliesDoNotQualify()
    {
        for (int id : new int[] {ItemID._4DOSEDIVINECOMBAT, ItemID._1DOSEDIVINEMAGIC,
            ItemID._1DOSEDIVINERANGE, ItemID._4DOSEDIVINEBATTLEMAGE,
            ItemID._1DOSEDIVINEBASTION, ItemID.SATURATED_HEART, ItemID.TOA_SUPPLY_STATS_1,
            ItemID.NZONE1DOSEOVERLOADPOTION, ItemID.VIAL_EMPTY})
        {
            assertTrue("Excluded source " + id, supplies(id).isEmpty());
        }
    }

    @Test
    public void onlyEdibleFullAndHalfPiesQualifyForTheirSkills()
    {
        assertEquals(EnumSet.of(Skill.SLAYER), supplies(ItemID.WILD_PIE));
        assertEquals(EnumSet.of(Skill.SLAYER), supplies(ItemID.HALF_WILD_PIE));
        assertEquals(EnumSet.of(Skill.AGILITY), supplies(ItemID.SUMMER_PIE));
        assertEquals(EnumSet.of(Skill.AGILITY), supplies(ItemID.HALF_SUMMER_PIE));
        assertTrue(supplies(ItemID.UNCOOKED_WILD_PIE).isEmpty());
    }

    @Test
    public void imbuedHeartRequiresReadinessAndInvalidItemsAreIgnored()
    {
        Item[] heart = {new Item(ItemID.IMBUED_HEART, 1)};
        assertTrue(BoostItems.available(heart, false).isEmpty());
        assertEquals(EnumSet.of(Skill.MAGIC), BoostItems.available(heart, true));
        assertTrue(BoostItems.available(null, true).isEmpty());
        assertTrue(BoostItems.available(new Item[] {null, new Item(-1, 0),
            new Item(ItemID._4DOSE2COMBAT, 0)}, true).isEmpty());
    }
}

package com.frazersan.overheadreminders;

import java.util.EnumMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BoostReminderControllerTest
{
    private Client client;
    private Player player;
    private ItemContainer inventory;
    private OverheadNotificationsConfig config;
    private NotificationStore store;
    private BoostReminderController reminders;
    private AtomicLong clock;
    private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);

    @Before
    public void setup()
    {
        client = mock(Client.class);
        player = mock(Player.class);
        inventory = mock(ItemContainer.class);
        config = mock(OverheadNotificationsConfig.class, CALLS_REAL_METHODS);
        when(config.meleeBoostUseGlobalTimer()).thenReturn(false);
        when(config.magicBoostUseGlobalTimer()).thenReturn(false);
        when(config.rangedBoostUseGlobalTimer()).thenReturn(false);
        when(config.wildPieUseGlobalTimer()).thenReturn(false);
        when(config.summerPieUseGlobalTimer()).thenReturn(false);
        when(config.showOutOfSupplies()).thenReturn(false);
        clock = new AtomicLong();
        store = new NotificationStore(clock::get);
        reminders = new BoostReminderController(client, config, store);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getLocalPlayer()).thenReturn(player);
        when(player.getInteracting()).thenReturn(mock(NPC.class));
        when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
        items();
        for (Skill skill : Skill.values())
        {
            when(client.getRealSkillLevel(skill)).thenReturn(90);
            when(client.getBoostedSkillLevel(skill)).thenReturn(90);
            when(client.getSkillExperience(skill)).thenReturn(1000);
            xp.put(skill, 1000);
        }
        reminders.onGameTick();
    }

    private void items(int... ids)
    {
        Item[] items = new Item[ids.length];
        for (int i = 0; i < ids.length; i++)
        {
            items[i] = new Item(ids[i], 1);
        }
        when(inventory.getItems()).thenReturn(items);
    }

    private void bonus(Skill skill, int bonus)
    {
        when(client.getBoostedSkillLevel(skill)).thenReturn(90 + bonus);
    }

    private void activity(Skill skill)
    {
        int nextXp = xp.get(skill) + 10;
        xp.put(skill, nextXp);
        when(client.getSkillExperience(skill)).thenReturn(nextXp);
        reminders.onStatChanged(new StatChanged(skill, nextXp, client.getRealSkillLevel(skill),
            client.getBoostedSkillLevel(skill)));
    }

    private void assertOnly(String key)
    {
        assertEquals(1, store.snapshot().size());
        assertEquals(key, store.snapshot().get(0).key);
    }

    @Test
    public void meleeNeedsCombatActivityAndMatchingInventorySupply()
    {
        when(config.meleeBoostEnabled()).thenReturn(true);
        items(ItemID._4DOSE2COMBAT);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
        activity(Skill.STRENGTH);
        reminders.onGameTick();
        assertOnly("Melee Boost");
    }

    @Test
    public void idleNpcInteractionAndNonCombatXpDoNotTrigger()
    {
        when(config.meleeBoostEnabled()).thenReturn(true);
        items(ItemID._4DOSE2COMBAT);
        reminders.onGameTick();
        activity(Skill.AGILITY);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
        when(player.getInteracting()).thenReturn(null);
        activity(Skill.STRENGTH);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
    }

    @Test
    public void noInventoryPotionAndWrongPotionDoNotTrigger()
    {
        when(config.meleeBoostEnabled()).thenReturn(true);
        activity(Skill.STRENGTH);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
        items(ItemID._4DOSERANGERSPOTION);
        activity(Skill.STRENGTH);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
    }

    @Test
    public void strengthOnlyPotionDoesNotDemandAnAttackBoost()
    {
        when(config.meleeBoostEnabled()).thenReturn(true);
        when(config.meleeBoostThreshold()).thenReturn(3);
        items(ItemID._4DOSE2STRENGTH);
        bonus(Skill.STRENGTH, 4);
        reminders.onGameTick();
        activity(Skill.ATTACK);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
        bonus(Skill.STRENGTH, 3);
        activity(Skill.ATTACK);
        reminders.onGameTick();
        assertOnly("Melee Boost");
    }

    @Test
    public void thresholdIsBonusAboveBaseAndTimeoutDoesNotRepeatUntilReboosted()
    {
        when(config.meleeBoostEnabled()).thenReturn(true);
        when(config.meleeBoostThreshold()).thenReturn(3);
        when(config.meleeBoostTimeout()).thenReturn(8);
        items(ItemID._1DOSE2STRENGTH);
        bonus(Skill.STRENGTH, 4);
        reminders.onGameTick();
        activity(Skill.STRENGTH);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
        bonus(Skill.STRENGTH, 3);
        activity(Skill.STRENGTH);
        reminders.onGameTick();
        assertOnly("Melee Boost");
        clock.set(7_999_999_999L);
        assertOnly("Melee Boost");
        clock.set(8_000_000_000L);
        activity(Skill.STRENGTH);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
        bonus(Skill.STRENGTH, 15);
        reminders.onGameTick();
        bonus(Skill.STRENGTH, 3);
        activity(Skill.STRENGTH);
        reminders.onGameTick();
        assertOnly("Melee Boost");
    }

    @Test
    public void reboostClearsItsOwnRowWithoutClearingOtherReminders()
    {
        when(config.meleeBoostEnabled()).thenReturn(true);
        when(config.magicBoostEnabled()).thenReturn(true);
        items(ItemID._4DOSE2COMBAT, ItemID._4DOSE1MAGIC);
        activity(Skill.STRENGTH);
        activity(Skill.MAGIC);
        reminders.onGameTick();
        assertEquals(2, store.snapshot().size());
        bonus(Skill.STRENGTH, 15);
        bonus(Skill.ATTACK, 15);
        reminders.onGameTick();
        assertOnly("Magic Boost");
    }

    @Test
    public void restoringDrainedStatToBaseDoesNotPretendItWasReboosted()
    {
        when(config.magicBoostEnabled()).thenReturn(true);
        items(ItemID._4DOSE1MAGIC);
        bonus(Skill.MAGIC, -2);
        activity(Skill.MAGIC);
        reminders.onGameTick();
        assertOnly("Magic Boost");
        bonus(Skill.MAGIC, 0);
        reminders.onGameTick();
        assertOnly("Magic Boost");
        bonus(Skill.MAGIC, 4);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
    }

    @Test
    public void finalPotionDoseAndInventoryRemovalClearCombatWarning()
    {
        when(config.rangedBoostEnabled()).thenReturn(true);
        items(ItemID._1DOSERANGERSPOTION);
        activity(Skill.RANGED);
        reminders.onGameTick();
        assertOnly("Ranged Boost");
        items(ItemID.VIAL_EMPTY);
        bonus(Skill.RANGED, 13);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
    }

    @Test
    public void oneAttackChecksAllEnabledInventorySupportedCombatBoosts()
    {
        when(config.meleeBoostEnabled()).thenReturn(true);
        when(config.magicBoostEnabled()).thenReturn(true);
        when(config.rangedBoostEnabled()).thenReturn(true);
        items(ItemID._4DOSE2STRENGTH, ItemID._4DOSERANGERSPOTION, ItemID._4DOSE1MAGIC);
        activity(Skill.DEFENCE);
        reminders.onGameTick();
        assertEquals(3, store.snapshot().size());
    }
    @Test
    public void activeDivineAndSaturatedEffectsSuppressDecayingBoostReminder()
    {
        when(config.magicBoostEnabled()).thenReturn(true);
        items(ItemID._4DOSE1MAGIC);
        when(client.getVarbitValue(VarbitID.DIVINEMAGIC_POTION_TIME)).thenReturn(100);
        activity(Skill.MAGIC);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
        when(client.getVarbitValue(VarbitID.DIVINEMAGIC_POTION_TIME)).thenReturn(0);
        when(client.getVarbitValue(VarbitID.SATURATED_HEART_TIME)).thenReturn(100);
        activity(Skill.MAGIC);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
    }

    @Test
    public void saltsAndOverloadsSuppressCombatBoostWarnings()
    {
        when(config.meleeBoostEnabled()).thenReturn(true);
        items(ItemID._4DOSE2COMBAT);
        for (int varbit : new int[] {VarbitID.TOA_MIDRAIDLOOT_STATS_TIMER,
            VarbitID.RAIDS_OVERLOAD_TIMER, VarbitID.NZONE_OVERLOAD_POTION_EFFECTS})
        {
            when(client.getVarbitValue(varbit)).thenReturn(100);
            activity(Skill.STRENGTH);
            reminders.onGameTick();
            assertTrue(store.snapshot().isEmpty());
            when(client.getVarbitValue(varbit)).thenReturn(0);
        }
    }

    @Test
    public void imbuedHeartMustBeReadyAndReboostClearsItsAlert()
    {
        when(config.magicBoostEnabled()).thenReturn(true);
        items(ItemID.IMBUED_HEART);
        when(client.getVarbitValue(VarbitID.IMBUED_HEART_TIMER)).thenReturn(10);
        activity(Skill.MAGIC);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
        when(client.getVarbitValue(VarbitID.IMBUED_HEART_TIMER)).thenReturn(0);
        activity(Skill.MAGIC);
        reminders.onGameTick();
        assertOnly("Magic Boost");
        bonus(Skill.MAGIC, 10);
        when(client.getVarbitValue(VarbitID.IMBUED_HEART_TIMER)).thenReturn(100);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
    }

    @Test
    public void pieNeedsObservedBoostThenWarnsWithoutCombatAndThroughFinalHalf()
    {
        when(config.wildPieEnabled()).thenReturn(true);
        when(config.wildPieThreshold()).thenReturn(1);
        items(ItemID.HALF_WILD_PIE);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
        // Eating the final half updates inventory before the next game tick.
        items(ItemID.VIAL_EMPTY);
        bonus(Skill.SLAYER, 5);
        reminders.onGameTick();
        bonus(Skill.SLAYER, 1);
        reminders.onGameTick();
        assertOnly("Wild Pie");
        clock.set(15_000_000_000L);
        reminders.onGameTick();
        assertTrue(store.snapshot().isEmpty());
    }

    @Test
    public void pieReboostClearsAndRearmsAndBothPiesStack()
    {
        when(config.wildPieEnabled()).thenReturn(true);
        when(config.summerPieEnabled()).thenReturn(true);
        items(ItemID.WILD_PIE, ItemID.SUMMER_PIE);
        bonus(Skill.SLAYER, 5);
        bonus(Skill.AGILITY, 5);
        reminders.onGameTick();
        bonus(Skill.SLAYER, 0);
        bonus(Skill.AGILITY, 0);
        reminders.onGameTick();
        assertEquals(2, store.snapshot().size());
        bonus(Skill.SLAYER, 5);
        reminders.onGameTick();
        assertOnly("Summer Pie");
        bonus(Skill.SLAYER, 0);
        reminders.onGameTick();
        assertEquals(2, store.snapshot().size());
    }

    @Test
    public void unrelatedBoostWithoutPieDoesNotStartPieReminder()
    {
        when(config.wildPieEnabled()).thenReturn(true);
        bonus(Skill.SLAYER, 5);
        reminders.onGameTick();
