        assertEquals(5, store.snapshot().size());
        Skill[] skills = {Skill.STRENGTH, Skill.MAGIC, Skill.RANGED, Skill.SLAYER, Skill.AGILITY};
        for (int i = 0; i < skills.length; i++)
