    }
}

package com.frazersan.overheadreminders;

import java.util.HashMap;
import java.util.Map;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class ConfigDefaultsMigrationTest
{
    private ConfigManager manager(Map<String, String> values)
    {
        ConfigManager manager = mock(ConfigManager.class);
        when(manager.getConfiguration(eq("overheadreminder"), anyString()))
            .thenAnswer(call -> values.get(call.getArgument(1)));
        doAnswer(call -> {
            values.put(call.getArgument(1), call.getArgument(2).toString());
            return null;
        }).when(manager).setConfiguration(eq("overheadreminder"), anyString(), any());
        return manager;
    }

    @Test
    public void storedOldDefaultsBecomeTitleCaseAndFifteenSeconds()
    {
        Map<String, String> values = new HashMap<>();
        values.put("overheadDisplayTime", "3");
        values.put("lowPrayerDuration", "0");
        values.put("lowPrayerMessage", "LOW PRAYER!");
        values.put("meleeBoostTimeout", "0");
        values.put("rangedBoostMessage", "RANGED BOOST LOW!");
        values.put("summerPieMessage", "AGILITY BOOST LOW!");
        ConfigDefaultsMigration.apply(manager(values));
        assertEquals("15", values.get("overheadDisplayTime"));
        assertEquals("0", values.get("lowPrayerDuration"));
        assertEquals("0", values.get("meleeBoostTimeout"));
        assertEquals("Low Prayer", values.get("lowPrayerMessage"));
        assertEquals("Drink Range Boost", values.get("rangedBoostMessage"));
        assertEquals("Agility Boost", values.get("summerPieMessage"));
    }

    @Test
    public void customValuesAndSubsequentEditsArePreserved()
    {
        Map<String, String> values = new HashMap<>();
        values.put("overheadDisplayTime", "8");
        values.put("meleeBoostMessage", "Drink strength");
        ConfigManager manager = manager(values);
        ConfigDefaultsMigration.apply(manager);
        assertEquals("8", values.get("overheadDisplayTime"));
        assertEquals("Drink strength", values.get("meleeBoostMessage"));
        values.put("overheadDisplayTime", "3");
        values.put("meleeBoostMessage", "MELEE BOOST LOW!");
        ConfigDefaultsMigration.apply(manager);
        assertEquals("3", values.get("overheadDisplayTime"));
        assertEquals("MELEE BOOST LOW!", values.get("meleeBoostMessage"));
    }

    @Test
    public void missingValuesUseNewDefaultsWithoutCreatingOverrides()
    {
        Map<String, String> values = new HashMap<>();
        ConfigDefaultsMigration.apply(manager(values));
        assertFalse(values.containsKey("overheadDisplayTime"));
        assertFalse(values.containsKey("summerPieMessage"));
        OverheadNotificationsConfig config = mock(OverheadNotificationsConfig.class, CALLS_REAL_METHODS);
        assertEquals(15, config.overheadDisplayTime());
        assertEquals(15, config.lowPrayerDuration());
        assertEquals(15, config.meleeBoostTimeout());
        assertEquals(15, config.magicBoostTimeout());
        assertEquals(15, config.rangedBoostTimeout());
        assertEquals(15, config.wildPieTimeout());
        assertEquals(15, config.summerPieTimeout());
        assertEquals("Agility Boost", config.summerPieMessage());
    }
    @Test
    public void actionDefaultsUpdateOnceWithoutChangingCustomMessagesOrEnabledChoices()
    {
        Map<String, String> values = new HashMap<>();
        values.put("tidyDefaultsRevision", "1");
        values.put("enableLowPrayer", "true");
        values.put("divinePotMessage", "Divine Expired!");
        values.put("thrallMessage", "My thrall");
        values.put("prayerRegenMessage", "Prayer regeneration potion Expired!");
        ConfigManager manager = manager(values);
        ConfigDefaultsMigration.apply(manager);
        assertEquals("Drink Divine", values.get("divinePotMessage"));
        assertEquals("My thrall", values.get("thrallMessage"));
        assertEquals("true", values.get("enableLowPrayer"));
        assertEquals("Prayer regeneration potion Expired!", values.get("prayerRegenMessage"));
        values.put("divinePotMessage", "Divine Expired!");
        ConfigDefaultsMigration.apply(manager);
        assertEquals("Divine Expired!", values.get("divinePotMessage"));
    }

    @Test
    public void freshReminderDefaultsAreAllDisabled() throws Exception
    {
        OverheadNotificationsConfig config = mock(OverheadNotificationsConfig.class, CALLS_REAL_METHODS);
        for (java.lang.reflect.Method method : OverheadNotificationsConfig.class.getDeclaredMethods())
        {
            if (method.isDefault() && method.getReturnType() == boolean.class)
            {
                assertEquals(method.getName(), (method.getName().endsWith("UseGlobalTimer") || method.getName().equals("showOutOfSupplies")), method.invoke(config));
            }
        }
        assertEquals("Drink Divine", config.divinePotMessage());
        assertEquals("Cast Thrall", config.thrallMessage());
        assertEquals("Invigorate Saturated Heart", config.saturatedHeartMessage());
    }
    @Test
    public void hornActiveDefaultUpdatesOnceAndZeroDurationsArePreserved()
    {
        Map<String, String> values = new HashMap<>();
        values.put("soulflameHornMessage", "Blow Soulflame Horn");
        values.put("overheadDisplayTime", "0");
        values.put("lowPrayerDuration", "0");
        values.put("meleeBoostTimeout", "0");
        ConfigManager manager = manager(values);
        ConfigDefaultsMigration.apply(manager);
        assertEquals("Soulflame Horn Active", values.get("soulflameHornMessage"));
        assertEquals("0", values.get("overheadDisplayTime"));
        assertEquals("0", values.get("lowPrayerDuration"));
        assertEquals("0", values.get("meleeBoostTimeout"));
        values.put("soulflameHornMessage", "Blow Soulflame Horn");
        ConfigDefaultsMigration.apply(manager);
        assertEquals("Blow Soulflame Horn", values.get("soulflameHornMessage"));
    }
    @Test
    public void upgradingPreservesCustomTimerSelectionsAndExplicitGlobalChoices()
    {
        Map<String, String> values = new HashMap<>();
        values.put("lowPrayerDuration", "8");
        values.put("meleeBoostTimeout", "0");
        values.put("magicBoostTimeout", "15");
        values.put("rangedBoostTimeout", "25");
        values.put("rangedBoostUseGlobalTimer", "true");
        ConfigManager manager = manager(values);
        ConfigDefaultsMigration.apply(manager);
        assertEquals("false", values.get("lowPrayerUseGlobalTimer"));
        assertEquals("false", values.get("meleeBoostUseGlobalTimer"));
        assertFalse(values.containsKey("magicBoostUseGlobalTimer"));
        assertEquals("true", values.get("rangedBoostUseGlobalTimer"));
        values.put("lowPrayerUseGlobalTimer", "true");
        ConfigDefaultsMigration.apply(manager);
        assertEquals("true", values.get("lowPrayerUseGlobalTimer"));
    }
}

package com.frazersan.overheadreminders;

import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class InventorySupplyCheckerTest
{
    private Client client;
    private ItemContainer inventory;
    private InventorySupplyChecker supplies;
    private int nextId;

    @Before
    public void setup()
    {
        client = mock(Client.class);
        inventory = mock(ItemContainer.class);
        when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
        supplies = new InventorySupplyChecker(client);
        nextId = 500000;
    }

    private int item(String name, boolean drinkable)
    {
        int id = nextId++;
        ItemComposition definition = mock(ItemComposition.class);
        when(definition.getName()).thenReturn(name);
        when(definition.getNote()).thenReturn(-1);
        when(definition.getInventoryActions()).thenReturn(drinkable ? new String[] {"Drink", null, "Drop"} : new String[] {"Use", "Drop"});
        when(client.getItemDefinition(id)).thenReturn(definition);
        when(inventory.getItems()).thenReturn(new Item[] {new Item(id, 1)});
        return id;
    }

    @Test
    public void potionsAndMixesOfAllDosesAndRaidTiersQualifyForMatchingReminder()
    {
        String[][] cases = {
            {"Divine super combat potion(1)", "Divine Pot"},
            {"Divine bastion potion(4)", "Divine Pot"},
            {"Stamina potion(1)", "Stamina"}, {"Stamina mix(2)", "Stamina"},
            {"Extended stamina potion(4)", "Stamina"},
            {"Prayer regeneration potion(3)", "Prayer Regen"},
            {"Prayer enhance (+)(4)", "Prayer Enhance"},
            {"Prayer enhance (-)(1)", "Prayer Enhance"},
            {"Surge potion(1)", "Surge"}, {"Antipoison(4)", "AntiPoison"},
            {"Superantipoison(1)", "AntiPoison"}, {"Antidote++(3)", "AntiPoison"},
            {"Antipoison mix(2)", "AntiPoison"}, {"Antipoison (+)(4)", "AntiPoison"},
            {"Anti-venom+(1)", "Venom"}, {"Extended anti-venom+(4)", "Venom"},
            {"Antifire potion(1)", "AntiFire"}, {"Antifire mix(2)", "AntiFire"},
            {"Extended antifire(4)", "AntiFire"}, {"Super antifire potion(4)", "AntiFire"},
            {"Extended super antifire mix(1)", "AntiFire"},
            {"Overload (+)(4)", "Overload"}, {"Overload (-)(1)", "Overload"},
            {"Overload(1)", "Overload"}
        };
        for (String[] entry : cases)
        {
            item(entry[0], true);
            supplies.update();
            assertTrue(entry[0], supplies.visible(entry[1]));
        }
    }

    @Test
    public void heartAndSaltsDoNotRequireADrinkActionAndCannotStandInForEachOther()
    {
        item("Saturated heart", false);
        supplies.update();
        assertTrue(supplies.visible("Saturated Heart"));
        assertFalse(supplies.visible("Smelling Salt"));
        item("Smelling salts(1)", false);
        supplies.update();
        assertTrue(supplies.visible("Smelling Salt"));
        assertFalse(supplies.visible("Saturated Heart"));
    }

    @Test
    public void notedEmptyMissingAndNonDrinkableItemsDoNotQualify()
    {
        int noted = item("Antifire potion(4)", true);
        when(client.getItemDefinition(noted).getNote()).thenReturn(799);
        supplies.update();
        assertFalse(supplies.visible("AntiFire"));
        int empty = item("Antifire potion(4)", true);
        when(inventory.getItems()).thenReturn(new Item[] {new Item(empty, 0), null});
        supplies.update();
        assertFalse(supplies.visible("AntiFire"));
        item("Antifire potion (unf)", false);
        supplies.update();
        assertFalse(supplies.visible("AntiFire"));
        when(client.getItemContainer(InventoryID.INV)).thenReturn(null);
        supplies.update();
        assertFalse(supplies.visible("AntiFire"));
    }

    @Test
    public void suppliesDisappearAndReturnWithoutChangingRealNotificationOrItsTimeout()
    {
        NotificationStore store = new NotificationStore(() -> 0L);
        store.show("AntiFire", "Drink Antifire", java.awt.Color.RED, 15);
        int id = item("Antifire potion(1)", true);
        supplies.update();
        assertTrue(supplies.visible("AntiFire"));
        when(inventory.getItems()).thenReturn(new Item[0]);
        supplies.update();
        assertFalse(supplies.visible("AntiFire"));
        assertEquals(1, store.snapshot().size());
        when(inventory.getItems()).thenReturn(new Item[] {new Item(id, 1)});
        supplies.update();
        assertTrue(supplies.visible("AntiFire"));
        assertEquals(15_000_000_000L, store.snapshot().get(0).expiresAt);
        verify(client, times(1)).getItemDefinition(id);
    }

    @Test
    public void prayerSpellsPiesAndActiveHornDoNotDependOnHavingAnItem()
    {
        supplies.update();
        for (String key : new String[] {"Low Prayer", "Thrall", "Death Charge", "Mark of Darkness", "Ward of Arceuus", "Wild Pie", "Summer Pie", "Soulflamehorn"})
            assertTrue(key, supplies.visible(key));
    }

    @Test
    public void matchingNormalBoostSuppliesUseExistingItemFamilies()
    {
        when(inventory.getItems()).thenReturn(new Item[] {new Item(ItemID.STRENGTH4, 1)});
        supplies.update();
        assertTrue(supplies.visible("Melee Boost"));
        assertFalse(supplies.visible("Magic Boost"));
        assertFalse(supplies.visible("Ranged Boost"));
        when(inventory.getItems()).thenReturn(new Item[] {new Item(ItemID._4DOSE1MAGIC, 1), new Item(ItemID._4DOSERANGERSPOTION, 1)});
        supplies.update();
        assertFalse(supplies.visible("Melee Boost"));
        assertTrue(supplies.visible("Magic Boost"));
        assertTrue(supplies.visible("Ranged Boost"));
    }

    @Test
    public void antivenomAlsoCountsAsAPoisonRemedyAndResetDropsCachedInventory()
    {
        item("Anti-venom+(1)", true);
        supplies.update();
        assertTrue(supplies.visible("Venom"));
        assertTrue(supplies.visible("AntiPoison"));
        supplies.reset();
        assertFalse(supplies.visible("Venom"));
    }
    @Test
    public void outOfSupplyNamesRememberRealDoseFreeNameAndStockReturningRestoresPrompt()
    {
        int id = item("Extended super antifire(1)", true);
        supplies.update();
        assertTrue(supplies.visible("AntiFire"));
        when(inventory.getItems()).thenReturn(new Item[0]);
        supplies.update();
        assertFalse(supplies.visible("AntiFire"));
        assertEquals("Out of Extended super antifire", supplies.outOfMessage("AntiFire"));
        when(inventory.getItems()).thenReturn(new Item[] {new Item(id, 1)});
        supplies.update();
        assertTrue(supplies.visible("AntiFire"));
    }

    @Test
    public void adrenalineBothDosesAreRecognisedAndMissingHistoryUsesSensibleName()
    {
        assertEquals("Out of Liquid Adrenaline", supplies.outOfMessage("Liquid Adrenaline"));
        for (String name : new String[] {"Liquid adrenaline(1)", "Liquid adrenaline(2)"})
        {
            item(name, true);
            supplies.update();
            assertTrue(supplies.visible("Liquid Adrenaline"));
            when(inventory.getItems()).thenReturn(new Item[0]);
            supplies.update();
            assertEquals("Out of Liquid adrenaline", supplies.outOfMessage("Liquid Adrenaline"));
        }
    }
}

package com.frazersan.overheadreminders;

import java.awt.Color;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;
import static org.junit.Assert.*;

public class NotificationStoreTest
{
    @Test
    public void simultaneousTypesRetainOrderColorAndIndependentExpiry()
    {
        AtomicLong clock = new AtomicLong();
        NotificationStore store = new NotificationStore(clock::get);
        store.show("Low Prayer", "{0}!", Color.RED, 2);
        store.show("Thrall", "Thrall expired", Color.CYAN, 5);
        assertEquals(2, store.snapshot().size());
        assertEquals("Low Prayer!", store.snapshot().get(0).message);
        assertEquals(Color.CYAN, store.snapshot().get(1).color);
        clock.set(2_000_000_000L);
        assertEquals(1, store.snapshot().size());
        assertEquals("Thrall", store.snapshot().get(0).key);
        clock.set(5_000_000_000L);
        assertTrue(store.snapshot().isEmpty());
    }

    @Test
    public void duplicateDoesNotAddLineOrRefreshExpiry()
    {
        AtomicLong clock = new AtomicLong();
        NotificationStore store = new NotificationStore(clock::get);
        store.show("Horn", "first", Color.RED, 3);
        clock.set(2_000_000_000L);
        store.show("Horn", "duplicate", Color.BLUE, 10);
        assertEquals(1, store.snapshot().size());
        assertEquals("first", store.snapshot().get(0).message);
        clock.set(3_000_000_000L);
        assertTrue(store.snapshot().isEmpty());
        store.show("Horn", "new event", Color.BLUE, 3);
        assertEquals("new event", store.snapshot().get(0).message);
    }

    @Test
    public void blankOrTargetedRemovalDoesNotClearOtherTypes()
    {
        NotificationStore store = new NotificationStore(() -> 0L);
        store.show("Prayer", "low", Color.RED, 3);
        store.show("Horn", "active", Color.BLUE, 3);
        store.show("Horn", " ", Color.BLUE, 3);
        assertEquals(1, store.snapshot().size());
        store.remove("missing");
        assertEquals("Prayer", store.snapshot().get(0).key);
        store.clear();
        assertTrue(store.snapshot().isEmpty());
    }

    @Test
    public void formatsCountdownAndSanitizesMultilineMarkup()
    {
        NotificationStore store = new NotificationStore(() -> 0L);
        store.show("Prayer", "<col=ff0000>Low\nprayer</col>", null, 3);
        NotificationStore.Entry entry = store.snapshot().get(0);
        assertEquals("Low prayer", entry.displayText(0L, false));
        assertEquals("Low prayer (3s)", entry.displayText(1L, true));
        assertEquals("Low prayer (1s)", entry.displayText(2_999_999_999L, true));
        assertEquals(Color.WHITE, entry.color);
    }
    @Test
    public void zeroIsPermanentWithoutCountdownAndStillSupportsTargetedRemoval()
    {
        AtomicLong clock = new AtomicLong();
        NotificationStore store = new NotificationStore(clock::get);
        store.show("AntiFire", "Drink Antifire", Color.RED, 0);
        store.show("Thrall", "Cast Thrall", Color.CYAN, 300);
        clock.set(3_600_000_000_000L);
        assertEquals(1, store.snapshot().size());
        assertEquals("Drink Antifire", store.snapshot().get(0).displayText(clock.get(), true));
        store.show("AntiFire", "duplicate", Color.BLUE, 5);
